import hashlib

def mask_card(no):
    return no[:6] + "*" * (len(no) - 10) + no[-4:]

def pseudo(uid, salt="test-env-salt"):
    return "U" + hashlib.sha256((salt + uid).encode()).hexdigest()[:10]

row = {"uid": "kim1234", "card": "5409123412341234", "phone": "010-1234-5678"}
safe = {"uid": pseudo(row["uid"]), "card": mask_card(row["card"]), "phone": None}
print(safe)
print(pseudo("kim1234") == safe["uid"])

